using System.Collections;
using Astrea.BattleActions;
using LittleLeo;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DisruptiveKnuckles OmenData", menuName = "Data/Battle/Omens System/Omen Data/Hevelius/DisruptiveKnucklesOmenData")]
public class DisruptiveKnucklesOmenData : OnPlayerCorruptEnemyOmenData
{
	public override void ActivateOmen(GameObject target = null)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueBeforeMainActionAction(EnemyAnimationCoroutine(target));
	}

	private IEnumerator EnemyAnimationCoroutine(GameObject target)
	{
		yield return InvokeAlternatives.WaitForFrames(ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 1);
		if (!target.GetComponent<CorruptedAnimalCorruptionStats>().IsDefeated() && !target.GetComponent<CorruptedAnimalSpriteControl>().CorruptedAnimalData.AnimationData.CollapsedAstrea)
		{
			yield return new WaitForSeconds(0.7f);
			CorruptedAnimalSpriteControl component = target.GetComponent<CorruptedAnimalSpriteControl>();
			yield return ReferenceSingleton<CoroutineHandler>.Instance.Run(component.PlayAttackAnimation());
			CorruptedLightningAction corruptedLightningAction = BattleAction as CorruptedLightningAction;
			yield return ReferenceSingleton<CoroutineHandler>.Instance.Run(corruptedLightningAction.SingleTargetCast(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject, ActionValue, corruptedLightningAction.CorruptPurifyAmountWithModifier, target));
		}
	}

	public override string OmenConvertedDescription()
	{
		return GetOnCorruptEnemyDescription() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + Smart.Format(GetOmenRawLocalizedDescription(), BattleAction.GetActionDescription(ActionValue).LowercaseFirst());
	}
}
